/**
 * 수정 완료
 */
scwin.sbm_updateDef_submitdone = function(e) {
    console.log("결함 수정 완료:", e);

    try {
        var responseData = e.responseJSON;
        var elHeader = responseData ? responseData.elHeader : null;

        if (!elHeader || elHeader.resSuc == false) {
            var errorMsg = "수정에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            console.error("수정 실패:", errorMsg);
            $c.win.alert(errorMsg);
            return;
        }

        console.log("결함 수정 성공");
        $c.win.alert("수정되었습니다.");

        // 수정 성공 후 조회 모드로 전환
        scwin.currentMode = "view";
        scwin.setFormMode("view");

        // 파일 목록 새로고침
        scwin.loadDefFileList();

    } catch (error) {
        console.error("수정 응답 처리 중 오류:", error);
        $c.win.alert("수정 처리 중 오류가 발생했습니다.");
    }
};

