/**
 * 에디터 모드 설정 (UnitTestPopup과 동일)
 */
scwin.setEditorMode = function(isEditMode) {
    console.log("=== 에디터 모드 전환:", isEditMode ? "편집" : "조회", "===");

    try {
        // description 에디터 설정
        if (typeof editor_description !== 'undefined' && editor_description) {
            if (editor_description.setReadOnly) {
                editor_description.setReadOnly(!isEditMode);
                console.log("description 에디터 읽기전용 설정:", !isEditMode);
            }

            // 에디터 스타일 조정
            if (isEditMode) {
                editor_description.setStyle("border: 2px solid #98BED6; background-color: white;");
            } else {
                editor_description.setStyle("border: 1px solid #ddd; background-color: #f8f9fa;");
            }
        } else {
            console.warn("description 에디터를 찾을 수 없음");
        }

        // remarks 에디터 설정
        if (typeof editor_remarks !== 'undefined' && editor_remarks) {
            if (editor_remarks.setReadOnly) {
                editor_remarks.setReadOnly(!isEditMode);
                console.log("remarks 에디터 읽기전용 설정:", !isEditMode);
            }

            // 에디터 스타일 조정
            if (isEditMode) {
                editor_remarks.setStyle("border: 2px solid #98BED6; background-color: white;");
            } else {
                editor_remarks.setStyle("border: 1px solid #ddd; background-color: #f8f9fa;");
            }
        } else {
            console.warn("remarks 에디터를 찾을 수 없음");
        }

        // 조회 모드일 때 내용 업데이트
        if (!isEditMode) {
            setTimeout(function() {
                scwin.updateViewContent();
            }, 100);
        }

        console.log("=== 에디터 모드 설정 완료 ===");

    } catch(e) {
        console.error("에디터 읽기전용 설정 실패:", e);
    }
};

/**
 * 에디터 내용 설정 (UnitTestPopup과 동일)
 */
scwin.setEditorContent = function(description, remarks) {
    try {
        console.log("에디터 내용 설정 시작");

        if (editor_description) {
            var descContent = description || "";

            if (descContent && (descContent.includes('&lt;') || descContent.includes('&gt;') || descContent.includes('&quot;'))) {
                descContent = scwin.fullyDecodeHtml(descContent);
            }

            if (!descContent || descContent.trim() === "") {
                descContent = "<p>결함 설명이 없습니다.</p>";
            }

            if (editor_description.setHTML) {
                editor_description.setHTML(descContent);
                console.log("결함 설명 에디터 설정 완료");
            }
        }

        if (editor_remarks) {
            var remarksContent = remarks || "";

            if (remarksContent && (remarksContent.includes('&lt;') || remarksContent.includes('&gt;') || remarksContent.includes('&quot;'))) {
                remarksContent = scwin.fullyDecodeHtml(remarksContent);
            }

            if (!remarksContent || remarksContent.trim() === "") {
                remarksContent = "<p>비고사항이 없습니다.</p>";
            }

            if (editor_remarks.setHTML) {
                editor_remarks.setHTML(remarksContent);
                console.log("비고사항 에디터 설정 완료");
            }
        }

    } catch (error) {
        console.error("에디터 내용 설정 중 오류:", error);
    }
};

/**
 * HTML 엔티티 완전 디코딩
 */
scwin.fullyDecodeHtml = function(str) {
    if (!str) return str;

    var result = str;
    var attempts = 0;
    var maxAttempts = 5;

    while (attempts < maxAttempts && (result.includes('&lt;') || result.includes('&gt;') || result.includes('&quot;'))) {
        attempts++;
        var previousResult = result;

        result = result
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&nbsp;/g, ' ')
            .replace(/&amp;/g, '&');

        if (result === previousResult) break;
    }

    return result;
};

/**
 * 파일 그리드 액션 버튼 클릭
 */
scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_defAttVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    // 다운로드 또는 삭제 처리
    if (targetId && targetId.indexOf("download") >= 0) {
        scwin.downloadFile(fileId, fileName);
    } else if (targetId && targetId.indexOf("delete") >= 0) {
        scwin.deleteFile(fileId);
    } else {
        scwin.downloadFile(fileId, fileName);
    }
};

/**
 * 파일 다운로드
 */
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.src = downloadUrl;

        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 파일 삭제
 */
scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            scwin.currentFileId = fileId;
            $c.sbm.execute($p, sbm_deleteDefFile);
        }
    });
};

scwin.sbm_deleteDefFile_submit = function(e) {
