/**
 * 현재 사용자명 가져오기
 */
scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;

                if (headerScwin.USER_NAME) {
                    console.log("헤더에서 사용자 이름 가져옴:", headerScwin.USER_NAME);
                    return headerScwin.USER_NAME;
                }
            }
        }

        console.log("헤더에서 사용자 이름을 가져올 수 없음, 기본값 사용");
        return "현재 사용자";

    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "현재 사용자";
    }
};

/**
 * 결함 상태가 '완료'로 변경될 때 관련 테스트 상태 업데이트
 */
scwin.handleDefectStatusChange = function(newStatus) {
    if (newStatus === "완료") {
        var testId = dmp_defDetail.get("testId");
        if (testId) {
            // 관련된 단위테스트를 성공으로 변경하는 API 호출
            scwin.updateRelatedTestStatus(testId, "SUC");
        }
    }
};

/**
 * 관련 테스트 상태 업데이트
 */
scwin.updateRelatedTestStatus = function(testId, newStatus) {
    console.log("관련 테스트 상태 업데이트:", testId, newStatus);

    try {
        // Ajax 호출로 테스트 상태 업데이트
        fetch("/InsWebApp/UNIT001UpdateResult.pwkjson", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                unitTestVo: {
                    testCaseId: testId,
                    testStatus: newStatus,
                    updatedAt: new Date().toISOString()
                }
            })
        })
        .then(function(response) { return response.json(); })
        .then(function(data) {
            if (data.elHeader && data.elHeader.resSuc) {
                console.log("관련 테스트 상태 업데이트 완료");
            } else {
                console.warn("테스트 상태 업데이트 실패:", data.elHeader ? data.elHeader.resMsg : "알 수 없는 오류");
            }
        })
        .catch(function(error) {
            console.error("테스트 상태 업데이트 오류:", error);
        });
    } catch (e) {
        console.error("테스트 상태 업데이트 실패:", e);
    }
};
